"use client"

import * as React from "react"
import { CalendarDays } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Popover, PopoverTrigger, PopoverContent } from "@/components/ui/popover"
import { Calendar, type CalendarProps, type DateRange } from "@/components/wunderui/calendar"
import { cn } from "@/lib/utils"

function formatDate(date?: Date) {
  if (!date) return undefined
  // Fixed locale (as in Calendar), so server and browser render the same text.
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })
}

function formatRange(range?: DateRange) {
  if (!range?.from) return undefined
  return range.to ? `${formatDate(range.from)} – ${formatDate(range.to)}` : formatDate(range.from)
}

function addMonths(date: Date, n: number) {
  return new Date(date.getFullYear(), date.getMonth() + n, 1)
}

type DatePreset = { label: string; range: () => DateRange }

const startOfDay = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate())

/** A range cut to `min` and `max` (whole days). */
function clampRange(range: DateRange, min?: Date, max?: Date): DateRange {
  let from = range.from && startOfDay(range.from)
  let to = range.to && startOfDay(range.to)
  if (min) {
    const lo = startOfDay(min)
    if (from && from < lo) from = lo
    if (to && to < lo) to = lo
  }
  if (max) {
    const hi = startOfDay(max)
    if (from && from > hi) from = hi
    if (to && to > hi) to = hi
  }
  return { from, to }
}

/** The quick ranges of the Figma Date Picker · Type=presets sidebar. */
const DEFAULT_PRESETS: DatePreset[] = [
  { label: "Today", range: () => ({ from: new Date(), to: new Date() }) },
  { label: "Last 7 days", range: () => ({ from: daysAgo(6), to: new Date() }) },
  { label: "Last 30 days", range: () => ({ from: daysAgo(29), to: new Date() }) },
  { label: "Last 3 months", range: () => ({ from: addMonths(new Date(), -3), to: new Date() }) },
  { label: "Last 12 months", range: () => ({ from: addMonths(new Date(), -12), to: new Date() }) },
  { label: "Month to date", range: () => ({ from: new Date(new Date().getFullYear(), new Date().getMonth(), 1), to: new Date() }) },
  { label: "Year to date", range: () => ({ from: new Date(new Date().getFullYear(), 0, 1), to: new Date() }) },
]

function daysAgo(n: number) {
  const d = new Date()
  d.setDate(d.getDate() - n)
  return d
}

type DatePickerSingleProps = {
  mode?: "single"
  value?: Date
  defaultValue?: Date
  onValueChange?: (date: Date | undefined) => void
}

type DatePickerRangeProps = {
  mode: "range"
  value?: DateRange
  defaultValue?: DateRange
  onValueChange?: (range: DateRange | undefined) => void
  /** Quick-select sidebar (Figma: Type=presets). `true` uses the built-in presets. */
  presets?: boolean | DatePreset[]
  /** Months shown side by side. Defaults to 2 for range mode. */
  numberOfMonths?: 1 | 2
}

type DatePickerProps = (DatePickerSingleProps | DatePickerRangeProps) & {
  placeholder?: string
  /** Earliest day that can be picked (passed to Calendar). */
  min?: Date
  /** Latest day that can be picked (passed to Calendar). */
  max?: Date
  /** Days that cannot be picked: a list of dates or a test (passed to Calendar). */
  disabled?: CalendarProps["disabled"]
  className?: string
}

/**
 * DatePicker — mirrors the Figma Date Picker set: Type=single (one month),
 * Type=range (two months, start/end), Type=presets (range + quick-select sidebar).
 */
function DatePicker(props: DatePickerProps) {
  const { placeholder, className, min, max, disabled } = props
  const isRange = props.mode === "range"
  const [open, setOpen] = React.useState(false)
  const [uncontrolled, setUncontrolled] = React.useState<Date | DateRange | undefined>(props.defaultValue)
  const isControlled = props.value !== undefined
  const selected = isControlled ? props.value : uncontrolled
  const [draft, setDraft] = React.useState<Date | DateRange | undefined>(selected)
  const [month, setMonth] = React.useState<Date>(() => {
    const d = isRange ? (selected as DateRange | undefined)?.from : (selected as Date | undefined)
    return addMonths(d ?? new Date(), 0)
  })

  const presets = isRange ? (props.presets === true ? DEFAULT_PRESETS : props.presets || null) : null
  const months = isRange ? (props.numberOfMonths ?? 2) : 1

  function handleOpenChange(next: boolean) {
    if (next) setDraft(selected)
    setOpen(next)
  }

  function apply() {
    if (!isControlled) setUncontrolled(draft)
    if (isRange) (props as DatePickerRangeProps).onValueChange?.(draft as DateRange | undefined)
    else (props as DatePickerSingleProps).onValueChange?.(draft as Date | undefined)
    setOpen(false)
  }

  const display = isRange ? formatRange(selected as DateRange | undefined) : formatDate(selected as Date | undefined)
  const draftRange = draft as DateRange | undefined

  return (
    <Popover open={open} onOpenChange={handleOpenChange}>
      <PopoverTrigger render={<Button variant="plain" className={cn(isRange ? "w-72" : "w-56", "justify-start font-normal", className)} />}>
        <CalendarDays className="size-4" />
        {display ?? <span className="text-text-tertiary">{placeholder ?? (isRange ? "Pick a date range" : "Pick a date")}</span>}
      </PopoverTrigger>
      <PopoverContent aria-label={isRange ? "Choose a date range" : "Choose a date"} className="w-auto p-0">
        <div className="flex">
          {presets && (
            <div className="flex w-40 flex-col gap-0.5 border-r border-border p-3">
              {presets.map((p) => {
                // a preset is cut to min and max; one that falls entirely outside them is switched off
                const raw = p.range()
                const r = clampRange(raw, min, max)
                const unavailable = !raw.from || !raw.to || (!!min && startOfDay(raw.to) < startOfDay(min)) || (!!max && startOfDay(raw.from) > startOfDay(max))
                const active = draftRange?.from?.toDateString() === r.from?.toDateString() && draftRange?.to?.toDateString() === r.to?.toDateString()
                return (
                  <button key={p.label} type="button" disabled={unavailable} onClick={() => (setDraft(r), setMonth(addMonths(r.from ?? new Date(), 0)))} className={cn("rounded-lg px-3 py-2 disabled:pointer-events-none disabled:opacity-40 text-left text-xs font-medium transition-colors duration-fast ease-entrance", active ? "bg-subtle font-semibold text-foreground" : "text-text-secondary hover:bg-subtle hover:text-foreground")}>
                    {p.label}
                  </button>
                )
              })}
            </div>
          )}
          <div className="flex gap-6 p-3">
            {Array.from({ length: months }).map((_, i) =>
              isRange ? (
                <Calendar key={i} mode="range" selected={draftRange} onSelect={setDraft} month={addMonths(month, i)} onMonthChange={(m) => setMonth(addMonths(m, -i))} min={min} max={max} disabled={disabled} />
              ) : (
                <Calendar key={i} mode="single" selected={draft as Date | undefined} onSelect={setDraft} month={month} onMonthChange={setMonth} min={min} max={max} disabled={disabled} />
              )
            )}
          </div>
        </div>
        <div className="flex justify-end gap-2 border-t border-border p-3">
          <Button variant="plain" size="sm" onClick={() => setOpen(false)}>
            Cancel
          </Button>
          <Button variant="primary" size="sm" onClick={apply}>
            Apply
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  )
}

export { DatePicker, DEFAULT_PRESETS as datePickerPresets }
export type { DatePickerProps, DatePreset }

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})

"use client"

import * as React from "react"
import { ChevronLeft, ChevronRight } from "lucide-react"
import { IconButton } from "@/components/ui/icon-button"
import { cn } from "@/lib/utils"

const WEEKDAY_LABELS = ["M", "T", "W", "T", "F", "S", "S"]
const WEEKDAY_NAMES = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]

function isSameDay(a?: Date, b?: Date) {
  return !!a && !!b && a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate()
}

function startOfDay(d: Date) {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate())
}

function addDays(d: Date, n: number) {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate() + n)
}

/** The same day n months later, clamped to the last day of the target month (Jan 31 → Feb 28). */
function addMonthsClamped(d: Date, n: number) {
  const lastDay = new Date(d.getFullYear(), d.getMonth() + n + 1, 0).getDate()
  return new Date(d.getFullYear(), d.getMonth() + n, Math.min(d.getDate(), lastDay))
}

function getMonthGrid(month: Date) {
  const year = month.getFullYear()
  const m = month.getMonth()
  const firstOfMonth = new Date(year, m, 1)
  const mondayOffset = (firstOfMonth.getDay() + 6) % 7
  const gridStart = new Date(year, m, 1 - mondayOffset)
  return Array.from({ length: 42 }, (_, i) => {
    const d = new Date(gridStart)
    d.setDate(gridStart.getDate() + i)
    return d
  })
}

type DateRange = { from?: Date; to?: Date }

/** Days that cannot be picked: a list of dates, or a test that returns true for a blocked day. */
type CalendarDisabled = Date[] | ((date: Date) => boolean)

type CalendarSingleProps = {
  mode?: "single"
  selected?: Date
  onSelect?: (date: Date) => void
}

type CalendarRangeProps = {
  mode: "range"
  selected?: DateRange
  onSelect?: (range: DateRange) => void
}

type CalendarProps = (CalendarSingleProps | CalendarRangeProps) & {
  month?: Date
  defaultMonth?: Date
  onMonthChange?: (month: Date) => void
  /** Earliest day that can be picked. Keyboard focus stops here and earlier months cannot be opened. */
  min?: Date
  /** Latest day that can be picked. Keyboard focus stops here and later months cannot be opened. */
  max?: Date
  /** Days inside min–max that cannot be picked. They stay reachable with the arrow keys and are announced as unavailable. */
  disabled?: CalendarDisabled
  className?: string
}

function Calendar({ mode = "single", selected, onSelect, month, defaultMonth, onMonthChange, min, max, disabled, className }: CalendarProps) {
  const initialSelected: Date | undefined = mode === "range" ? (selected as DateRange | undefined)?.from : (selected as Date | undefined)
  const [uncontrolledMonth, setUncontrolledMonth] = React.useState<Date>(
    () => defaultMonth ?? initialSelected ?? new Date()
  )
  const visibleMonth = month ?? uncontrolledMonth
  // The day that holds the grid's single tab stop, once the user has moved it (keyboard, click or month change).
  const [focusDay, setFocusDay] = React.useState<Date | null>(null)
  // Set by keyboard navigation: after the next render the tab-stop day receives DOM focus.
  const focusPending = React.useRef(false)
  const gridRef = React.useRef<HTMLDivElement>(null)
  const headingId = React.useId()

  const days = React.useMemo(() => getMonthGrid(visibleMonth), [visibleMonth])
  const today = React.useMemo(() => startOfDay(new Date()), [])
  const minDay = min ? startOfDay(min) : undefined
  const maxDay = max ? startOfDay(max) : undefined

  function outOfBounds(day: Date) {
    return (!!minDay && day < minDay) || (!!maxDay && day > maxDay)
  }

  function isDisabled(day: Date) {
    if (outOfBounds(day)) return true
    if (!disabled) return false
    return typeof disabled === "function" ? disabled(day) : disabled.some((d) => isSameDay(d, day))
  }

  function clamp(day: Date) {
    if (minDay && day < minDay) return minDay
    if (maxDay && day > maxDay) return maxDay
    return day
  }

  const inVisibleMonth = (d?: Date) =>
    !!d && d.getFullYear() === visibleMonth.getFullYear() && d.getMonth() === visibleMonth.getMonth()
  const inGrid = (d?: Date | null) => !!d && days.some((day) => isSameDay(day, d))

  // Roving tab stop (WAI-ARIA date grid): the moved-to day, else the selected day, else today,
  // else the first day of the month that can be reached — always a day of this grid.
  const firstOfMonth = new Date(visibleMonth.getFullYear(), visibleMonth.getMonth(), 1)
  const activeDay: Date =
    (focusDay && inGrid(focusDay) ? focusDay : undefined) ??
    (inVisibleMonth(initialSelected) ? startOfDay(initialSelected!) : undefined) ??
    (inVisibleMonth(today) ? today : undefined) ??
    (inVisibleMonth(clamp(firstOfMonth)) ? clamp(firstOfMonth) : firstOfMonth)

  React.useEffect(() => {
    if (!focusPending.current) return
    const target = gridRef.current?.querySelector<HTMLElement>("[data-tab-stop]")
    if (target) {
      focusPending.current = false
      target.focus()
    }
  })

  function changeMonth(next: Date) {
    if (!month) setUncontrolledMonth(next)
    onMonthChange?.(next)
  }

  const prevMonthEnd = new Date(visibleMonth.getFullYear(), visibleMonth.getMonth(), 0)
  const nextMonthStart = new Date(visibleMonth.getFullYear(), visibleMonth.getMonth() + 1, 1)
  // A month that lies completely outside min–max cannot be opened.
  const prevBlocked = !!minDay && prevMonthEnd < minDay
  const nextBlocked = !!maxDay && nextMonthStart > maxDay

  function stepMonth(n: number) {
    changeMonth(new Date(visibleMonth.getFullYear(), visibleMonth.getMonth() + n, 1))
    // The tab stop follows: same day in the new month, clamped to its length and to min–max.
    setFocusDay(clamp(addMonthsClamped(activeDay, n)))
  }

  function handleDayClick(day: Date) {
    setFocusDay(day)
    if (isDisabled(day)) return
    if (mode === "range") {
      const range = (selected as DateRange | undefined) ?? {}
      const onRangeSelect = onSelect as CalendarRangeProps["onSelect"]
      if (!range.from || (range.from && range.to)) {
        onRangeSelect?.({ from: day, to: undefined })
      } else if (day < range.from) {
        onRangeSelect?.({ from: day, to: range.from })
      } else {
        onRangeSelect?.({ from: range.from, to: day })
      }
    } else {
      ;(onSelect as CalendarSingleProps["onSelect"])?.(day)
    }
  }

  function handleKeyDown(event: React.KeyboardEvent, day: Date) {
    let next: Date | undefined
    const weekday = (day.getDay() + 6) % 7
    switch (event.key) {
      case "ArrowLeft": next = addDays(day, -1); break
      case "ArrowRight": next = addDays(day, 1); break
      case "ArrowUp": next = addDays(day, -7); break
      case "ArrowDown": next = addDays(day, 7); break
      case "Home": next = addDays(day, -weekday); break
      case "End": next = addDays(day, 6 - weekday); break
      case "PageUp": next = addMonthsClamped(day, event.shiftKey ? -12 : -1); break
      case "PageDown": next = addMonthsClamped(day, event.shiftKey ? 12 : 1); break
      case "Enter":
      case " ":
        event.preventDefault()
        handleDayClick(day)
        return
      default:
        return
    }
    event.preventDefault()
    next = clamp(next)
    if (!inVisibleMonth(next)) changeMonth(new Date(next.getFullYear(), next.getMonth(), 1))
    focusPending.current = true
    setFocusDay(next)
  }

  function dayState(day: Date) {
    if (mode === "range") {
      const range = selected as DateRange | undefined
      const isStart = isSameDay(day, range?.from)
      const isEnd = isSameDay(day, range?.to)
      const inRange = !!range?.from && !!range?.to && day > range.from && day < range.to
      return { selected: isStart || isEnd, inRange, rangeStart: isStart, rangeEnd: isEnd }
    }
    return { selected: isSameDay(day, selected as Date | undefined), inRange: false, rangeStart: false, rangeEnd: false }
  }

  const weeks = Array.from({ length: 6 }, (_, w) => days.slice(w * 7, w * 7 + 7))

  return (
    <div data-slot="calendar" className={cn("w-fit", className)}>
      <div className="mb-3 flex items-center justify-between">
        <IconButton
          type="button"
          variant="plain"
          size="sm"
          aria-label="Previous month"
          disabled={prevBlocked}
          onClick={() => stepMonth(-1)}
        >
          <ChevronLeft className="size-4" />
        </IconButton>
        <p id={headingId} aria-live="polite" className="text-sm font-semibold text-foreground">
          {/* Fixed locale like the weekday labels, so server and browser render the same text. */}
          {visibleMonth.toLocaleDateString("en-US", { month: "long", year: "numeric" })}
        </p>
        <IconButton
          type="button"
          variant="plain"
          size="sm"
          aria-label="Next month"
          disabled={nextBlocked}
          onClick={() => stepMonth(1)}
        >
          <ChevronRight className="size-4" />
        </IconButton>
      </div>
      <div ref={gridRef} role="grid" aria-labelledby={headingId} className="flex flex-col gap-y-1">
        <div role="row" className="grid grid-cols-7">
          {WEEKDAY_LABELS.map((label, i) => (
            <div
              key={i}
              role="columnheader"
              aria-label={WEEKDAY_NAMES[i]}
              className="flex h-8 items-center justify-center text-xs font-medium text-text-tertiary"
            >
              {label}
            </div>
          ))}
        </div>
        {weeks.map((week, w) => (
          <div key={w} role="row" className="grid grid-cols-7">
            {week.map((day, weekday) => {
              const outside = day.getMonth() !== visibleMonth.getMonth()
              const { selected: isSelected, inRange, rangeStart, rangeEnd } = dayState(day)
              const isToday = isSameDay(day, today)
              const isBlocked = isDisabled(day)
              const isTabStop = isSameDay(day, activeDay)
              // The band runs under the two end circles up to their centres, so it reads as one
              // continuous shape: the start circle covers its left half, the end circle its right half.
              const band = mode === "range" && !!(selected as DateRange | undefined)?.from && !!(selected as DateRange | undefined)?.to && !isSameDay((selected as DateRange).from, (selected as DateRange).to)
              return (
                <div
                  key={weekday}
                  role="gridcell"
                  aria-selected={isSelected}
                  className={cn(
                    "relative flex h-9 items-center justify-center",
                    inRange && "bg-accent",
                    // the band is rounded where a week starts and ends
                    inRange && weekday === 0 && "rounded-l-full",
                    inRange && weekday === 6 && "rounded-r-full",
                    band && rangeStart && "before:absolute before:inset-y-0 before:right-0 before:left-1/2 before:bg-accent before:content-['']",
                    band && rangeEnd && "before:absolute before:inset-y-0 before:right-1/2 before:left-0 before:bg-accent before:content-['']"
                  )}
                >
                  <button
                    type="button"
                    tabIndex={isTabStop ? 0 : -1}
                    data-tab-stop={isTabStop ? "" : undefined}
                    onClick={() => handleDayClick(day)}
                    onKeyDown={(e) => handleKeyDown(e, day)}
                    aria-label={day.toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric", year: "numeric" })}
                    aria-current={isToday ? "date" : undefined}
                    aria-disabled={isBlocked || undefined}
                    className={cn(
                      "relative flex size-8 items-center justify-center rounded-full text-sm transition-colors duration-fast ease-entrance hover:bg-muted/50",
                      outside && "text-text-tertiary",
                      !outside && !isSelected && "text-foreground",
                      isToday && !isSelected && "font-semibold text-text-link",
                      isSelected && "bg-primary text-primary-foreground hover:bg-primary/90",
                      isBlocked && "cursor-not-allowed opacity-40 hover:bg-transparent"
                    )}
                  >
                    {day.getDate()}
                  </button>
                </div>
              )
            })}
          </div>
        ))}
      </div>
    </div>
  )
}

export { Calendar }
export type { CalendarProps, DateRange }

import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"

// Same contrast rules as Button (see the long comment in button.tsx): hover on
// the filled variants darkens with brightness-95 instead of bg-*/90 (an alpha
// fill is LIGHTER than the solid fill on a white page: primary/brand 4.99 ->
// 4.17:1, destructive 5.04 -> 4.44:1, now 4.85 / 4.91:1). The gradient top stop
// was --gradient-start-3 (#6f74f5, 3.82:1 with a white icon, 3.52:1 on the old
// brightness-105 hover); it is now 85 % primary + 15 % brand-500, which is
// 4.73:1 at rest and 4.61:1 hovered. The light variant's icon is light-1000
// (5.93:1 on light-600) instead of light-900 (3.84:1), so a text label would pass too.
const iconButtonVariants = cva(
  "group/icon-button inline-flex shrink-0 items-center justify-center border border-transparent transition duration-fast ease-entrance outline-none select-none shadow-[0px_1px_1px_0px_rgba(16,24,40,0.05)] active:scale-[0.97] motion-reduce:active:scale-100 disabled:pointer-events-none disabled:opacity-40 focus-visible:border-ring focus-visible:outline-solid focus-visible:outline-1 focus-visible:outline-offset-2 focus-visible:outline-ring [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        plain: "bg-card border-border-control text-foreground hover:bg-muted/50",
        primary: "border-primary bg-primary text-primary-foreground hover:brightness-95",
        brand:
          "border-brand-primary bg-brand-primary text-brand-primary-foreground hover:brightness-95",
        gradient:
          "border-primary bg-gradient-to-b from-[color-mix(in_srgb,var(--primary)_85%,var(--brand-500))] to-primary text-primary-foreground shadow-[inset_0px_1px_2px_0px_rgba(255,255,255,0.35)] hover:brightness-95",
        dark: "bg-inverse text-text-inverse hover:bg-(--dark-400) hover:text-white",
        light: "bg-(--light-600) text-(--light-1000) hover:brightness-95",
        outline: "bg-card border-primary text-foreground hover:bg-primary/5",
        // Figma Type=ghost / destructive (added Sep 2026)
        ghost: "bg-transparent text-foreground shadow-none hover:bg-muted/50",
        destructive:
          "border-destructive bg-destructive text-destructive-foreground hover:brightness-95",
      },
      shape: {
        rounded: "rounded-md",
        circle: "rounded-full",
      },
      size: {
        sm: "size-8 [&_svg]:size-4",
        md: "size-9 [&_svg]:size-[18px]",
        lg: "size-10 [&_svg]:size-5",
        xl: "size-11 [&_svg]:size-[22px]",
        "2xl": "size-12 [&_svg]:size-6",
      },
    },
    defaultVariants: {
      variant: "primary",
      shape: "rounded",
      size: "md",
    },
  }
)

function IconButton({
  className,
  variant,
  shape,
  size,
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof iconButtonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant, shape, size, className }))}
      {...props}
    />
  )
}

export { IconButton, iconButtonVariants }

"use client"

import * as React from "react"
import { Popover as PopoverPrimitive } from "@base-ui/react/popover"
import { cn } from "@/lib/utils"

function Popover({ ...props }: PopoverPrimitive.Root.Props) {
  return <PopoverPrimitive.Root data-slot="popover" {...props} />
}

function PopoverTrigger({ ...props }: PopoverPrimitive.Trigger.Props) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />
}

function PopoverContent({
  className,
  sideOffset = 8,
  side,
  align,
  anchor,
  ...props
}: PopoverPrimitive.Popup.Props & Pick<PopoverPrimitive.Positioner.Props, "sideOffset" | "side" | "align" | "anchor">) {
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Positioner className="isolate z-50 outline-none" sideOffset={sideOffset} side={side} align={align} anchor={anchor}>
        <PopoverPrimitive.Popup
          data-slot="popover-content"
          className={cn(
            "z-50 rounded-lg border border-border bg-popover [--surface:var(--popover)] p-3 text-sm text-popover-foreground shadow-lg outline-none",
            "data-open:animate-in data-open:fade-in-0 origin-(--transform-origin) data-open:zoom-in-95 data-open:duration-base data-open:ease-overshoot data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-99 data-closed:duration-fast data-closed:ease-exit",
            className
          )}
          {...props}
        />
      </PopoverPrimitive.Positioner>
    </PopoverPrimitive.Portal>
  )
}

/** Closes the popover it sits in — render it as an icon button for an ×, or around Cancel/Apply. */
function PopoverClose({ ...props }: PopoverPrimitive.Close.Props) {
  return <PopoverPrimitive.Close data-slot="popover-close" {...props} />
}

export { Popover, PopoverTrigger, PopoverContent, PopoverClose }

